    /*//////////////////////////////////////////////////////////////
                              STRUCTS
    //////////////////////////////////////////////////////////////*/

    struct SimRequest {
        uint256 id;
        bytes32 lineId;
        address operatorAddress;
        address holder;
        uint256 createdAt;
        bool identityVerified;
        bool holderConfirmed;
        bool disputed;
